pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop internal c;
    Recorder internal rec;

    function setUp() public {
        c = new airdrop();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 v, address from, address to) public {
        vm.assume(to != address(0));

        address[] memory tos = new address[](1);
        tos[0] = to;

        rec.reset();
        try c.transfer(from, address(rec), tos, v) returns (bool ok) {
            assertTrue(
                !ok || (rec.count() == 1 && rec.lastFrom() == from && rec.lastTo() == to && rec.lastAmount() == v)
            );
        } catch {
            assertTrue(true);
        }
    }
}

contract Recorder {
    uint256 public count;
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;

    function reset() external {
        count = 0;
        lastFrom = address(0);
        lastTo = address(0);
        lastAmount = 0;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        count += 1;
        lastFrom = from;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}
